const p=$('Offer Confirmation Page Input').first().json;
const valid=$json.check_result?.valid===true;
const html=valid ? '<!doctype html><html><head><meta charset="utf-8"><meta name="referrer" content="no-referrer"><title>Confirm maintenance response</title></head><body><h1>Confirm '+p.decision+'</h1><p>Ticket #'+p.ticket+'. No assignment is made until your acceptance is processed.</p><form method="post" action="https://replace_n8n_host/webhook/cbm-wf1-offer"><input type="hidden" name="ticket" value="'+p.ticket+'"><input type="hidden" name="offer" value="'+p.offer+'"><input type="hidden" name="token" value="'+p.token+'"><input type="hidden" name="decision" value="'+p.decision+'"><button type="submit">Confirm '+p.decision+'</button></form></body></html>' : '<h1>Offer unavailable</h1><p>This link is invalid, expired, or the job has already been assigned.</p>';
return [{json:{html,statusCode:valid?200:410}}];

const result=$input.all().map(i=>i.json.response_result).find(Boolean);
if(!result) throw new Error('Response receipt missing');
return [{json:{...result,message:result.recorded?'Response received. Assignment is confirmed separately by email.':'This response is already recorded, invalid, or expired.'}}];

const b=$json.body||{};
if(!Number.isSafeInteger(b.ticketId)||b.ticketId<1||!/[0-3][0-9A-Za-z_$]{21}/.test(b.globalId||'')||String(b.globalId).length!==22
 || !['carpentry','plumbing','electrical','hvac','general'].includes(b.skill)||!Number.isInteger(b.severity)||b.severity<1||b.severity>5
 || typeof b.description!=='string'||!b.description.trim()||b.description.length>4000)throw new Error('Provide ticketId, IFC globalId, skill, severity 1–5, and description.');
return [{json:{ticketId:b.ticketId,globalId:b.globalId,skill:b.skill,severity:b.severity,description:b.description.trim()}}];

const active = o => ['SENDING','LIVE','UNCERTAIN'].includes(o.status);

const terminal = t => !['LOCALIZED','DISPATCHING'].includes(t.status);

function audit(c,type,detail={}) {c.state.audit.push({type,at:c.now.toISOString(),...detail});}

function block(c,reason) {c.state.halted=true;c.state.error=reason;audit(c,'OPERATOR_ACTION_REQUIRED',{reason});}

function context(request,row) {
  const state=row.state?JSON.parse(JSON.stringify(row.state)):null;
  const c={request,row,state,ticket:row.ticket,now:new Date(row.now),before:JSON.stringify(state),mail:null,config:state?.config||request.config,feedback:null};
  if(state) {
    state.audit ||= [];state.messages ||= {};state.offers ||= [];
    if(terminal(row.ticket))state.status=row.ticket.status;
    for(const m of Object.values(state.messages)) {
      if(m.status==='SENDING'&&c.now-Date.parse(m.claimed_at)>300000&&!(request.operation==='ack'&&request.receipt?.key===m.key)) {
        m.status='UNCERTAIN';const o=state.offers.find(o=>o.id===m.offer_id);if(o&&active(o))o.status='UNCERTAIN';
        block(c,`Delivery receipt missing for ${m.key}. Reconcile with Gmail before resending.`);
      }
    }
  }
  return c;
}

function facts(c) {
  const {state:s,ticket:t,row,now}=c;
  if(!t)return {ticket_id:null,outcome:'NO_TICKET',initialized:false};
  if(!s)return {ticket_id:t.id,outcome:Number(row.init_failures||0)>=3?'OPERATOR_ACTION_REQUIRED':'UNINITIALIZED',initialized:false};
  const offers=s.offers,notices=Object.values(s.messages),candidates=row.candidates||[];
  const available=s.shortlist.filter(id=>!offers.some(o=>o.technician_id===id)&&candidates.some(c=>Number(c.technician_id)===id));
  const pending=(row.inbox||[]).filter(i=>Number(i.id)>Number(s.response_cursor));
  const expired=offers.filter(o=>active(o)&&Date.parse(o.expires_at)<=now.getTime()),live=offers.filter(active);
  const urgent=Number(t.severity)>=4,cap=urgent?2:1,opening=s.messages.opening?.status;
  const beforeAppointment=!urgent||now.getTime()<Date.parse(s.urgent_start),dispatchOpen=!terminal(t);
  // Outcome verification is separate from the agent's choice of tools.
  const unfinished=pending.length>0||expired.length>0||notices.some(m=>m.status==='PENDING'&&!m.key.startsWith('offer:')&&(m.key!=='opening'||dispatchOpen))||
    (dispatchOpen&&opening==='SENT'&&((live.length<cap&&available.length>0&&beforeAppointment)||(live.length===0&&(available.length===0||!beforeAppointment))));
  const wakes=[...live.map(o=>Date.parse(o.expires_at)),...notices.filter(m=>m.status==='SENDING').map(m=>Date.parse(m.claimed_at)+300001)];
  const nextWake=s.halted?null:unfinished?now.toISOString():wakes.length?new Date(Math.min(...wakes)).toISOString():null;
  return {ticket_id:t.id,initialized:true,status:t.status,dispatch_status:s.status,
    outcome:s.halted?'OPERATOR_ACTION_REQUIRED':unfinished?'ACTION_REQUIRED':s.status==='ASSIGNED'?'ASSIGNED':s.status==='ESCALATED'?'ESCALATED':'WAITING',
    now:now.toISOString(),urgent,max_live_offers:cap,active_offer_count:live.length,urgent_start:s.urgent_start,original_date:s.original_date,
    opening_status:opening,pending_response_count:pending.length,expired_offer_count:expired.length,next_wake:nextWake,
    available_candidate_ids:available,error:s.halted?s.error:null,
    offers:offers.map(({token,...o})=>o),notices:notices.map(m=>({key:m.key,status:m.status,message_id:m.message_id||null})),
    candidates:s.shortlist.map(id=>{const v=candidates.find(x=>Number(x.technician_id)===id);return v?{technician_id:id,full_name:v.full_name,eligible:true,open_jobs:v.open_jobs,last_assigned_at:v.last_assigned_at,rating:v.rating}:{technician_id:id,eligible:false};})};
}

function finish(c) {
  const result=facts(c);if(c.feedback)result.operation_result=c.feedback;
  if(c.state){c.state.next_wake=c.request.operation==='failure'&&!c.state.halted?new Date(c.now.getTime()+60000).toISOString():result.next_wake;c.state.audit=c.state.audit.slice(-60);}
  return {write:c.request.operation!=='read'&&!!c.state&&JSON.stringify(c.state)!==c.before,state:c.state,mail:c.mail,result,feedback:c.feedback};
}

function reject(c,reason) {c.feedback={performed:false,reason};return finish(c);}

const escapeHtml = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function queue(c,key,to,subject,html,offerId=null) {c.state.messages[key] ||= {key,to,subject,html,offer_id:offerId,status:'PENDING'};}

function localDate(d) {return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}

function addDays(date,count,business=false) {
  const d=new Date(date+'T12:00:00Z');for(let n=0;n<count;){d.setUTCDate(d.getUTCDate()+1);if(!business||![0,6].includes(d.getUTCDay()))n++;}return d.toISOString().slice(0,10);
}

function atRome(date,hour) {
  const target=Date.parse(`${date}T${String(hour).padStart(2,'0')}:00:00Z`);let guess=target;
  for(let i=0;i<3;i++){
    const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).map(p=>[p.type,p.value]));
    guess+=target-Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}Z`);
  }return new Date(guess);
}

function details(c) {
  const t=c.ticket,e=escapeHtml;return `<p><b>Element:</b> ${e(t.ifc_name)} (${e(t.ifc_class)})<br><b>Issue:</b> ${e(t.description)}<br><b>Severity:</b> ${e(t.severity)}/5</p>`+
    (/^https:\/\//i.test(t.photo_before_url||'')?`<p><a href="${e(t.photo_before_url)}">Before photo</a></p>`:'');
}

function initialize(request,row) {
  const c=context(request,row);if(!c.ticket||c.state)return finish(c);
  if(terminal(c.ticket))return reject(c,'TICKET_ALREADY_TERMINAL');
  const urgent=Number(c.ticket.severity)>=4,date=addDays(localDate(new Date(c.ticket.created_at)),urgent?1:2,true);
  c.state={version:2,source_key:request.sourceKey,status:c.ticket.status,urgent,cap:urgent?2:1,urgent_start:urgent?atRome(date,8).toISOString():null,original_date:date,
    shortlist:(row.candidates||[]).slice(0,5).map(x=>Number(x.technician_id)),offers:[],messages:{},response_cursor:0,audit:[],halted:false,failures:0,config:JSON.parse(JSON.stringify(request.config))};
  audit(c,'DISPATCH_INITIALIZED');queue(c,'opening',c.config.fmEmail,`[CBM] New ticket #${c.ticket.id}: ${String(c.ticket.category||'').slice(0,80)}`,
    `<h3>New maintenance ticket #${c.ticket.id}</h3>${details(c)}<p>Eligible technicians will now be contacted automatically.</p>`);return finish(c);
}
const runOperation = initialize;
const row=$json.context,b=$('Validate FM Resume').first().json,el=$('Verify Resume Element').first().json;
if(!row.ticket||!['NEEDS_TRIAGE','ESCALATED'].includes(row.ticket.status))throw new Error('Only NEEDS_TRIAGE or ESCALATED tickets can resume.');
if(el.global_id!==b.globalId)throw new Error('IFC element identity mismatch.');
row.ticket={...row.ticket,status:'LOCALIZED',created_at:row.now,ifc_global_id:el.global_id,ifc_class:el.ifc_class,ifc_name:el.name,severity:b.severity,required_skill:b.skill,description:b.description};
row.state=null;
const result=runOperation({operation:'initialize',ticketId:b.ticketId,config:{"fmEmail":"REPLACE_FM_EMAIL@example.com","callbackBase":"https://REPLACE_N8N_HOST/webhook","model":"claude-sonnet-4-6","postgresCredentialId":"REPLACE_POSTGRES_CREDENTIAL_ID","postgresCredentialName":"CBM Postgres","gmailCredentialId":"REPLACE_GMAIL_CREDENTIAL_ID","gmailCredentialName":"CBM Gmail","anthropicCredentialId":"REPLACE_ANTHROPIC_CREDENTIAL_ID","anthropicCredentialName":"CBM Anthropic","knowledge":{"supabaseCredentialId":"REPLACE_SUPABASE_CREDENTIAL_ID","supabaseCredentialName":"CBM Supabase Knowledge","postgresCredentialId":"REPLACE_SUPABASE_POSTGRES_CREDENTIAL_ID","postgresCredentialName":"CBM Supabase Postgres","openaiCredentialId":"REPLACE_OPENAI_CREDENTIAL_ID","openaiCredentialName":"CBM OpenAI Embeddings","snapshotUrl":"http://127.0.0.1:8001/knowledge/snapshot","sourceCredentialId":"REPLACE_KNOWLEDGE_HEADER_CREDENTIAL_ID","sourceCredentialName":"CBM Knowledge Source Header"},"workflowIds":{"initialize":"d7bdaa41c660ddf514f47ca5732b05aa","offer_next":"8555b0e787152959ac42a92dc914182e","send_notices":"70f0d086a0627d430b5fa7ce5e262e05","process_events":"4572050930582ffecf96401f5d45633a","escalate":"7d48cc5ab0079a31980bf74bec758ec3","ack":"4361d78a5a6d12aa633dd66017a3f4db","failure":"b6faa41765004111126a29d6fdccb21a"}}},row);
return [{json:{ticketId:b.ticketId,revision:row.revision,fields:row.ticket,state:result.state}}];

const item=$input.first();
const data=await this.helpers.getBinaryDataBuffer(0,'data');
if(data.length>50*1024*1024)throw new Error('PDF exceeds the configured 50 MB document limit');
if(data.subarray(0,5).toString()!=='%PDF-')throw new Error('Source is not a PDF');
const fileName=String(item.binary.data.fileName||item.json.fileName||'');
if(!fileName||!/^[a-f0-9]{64}$/.test(item.json.source_sha256||''))throw new Error('PDF name or fingerprint missing');
const settings=$('Demo - Source Settings').first().json;
return [{json:{fileName,source_sha256:item.json.source_sha256,
 source_key:settings.sourceDirectory+'/'+fileName,pipeline_revision:settings.pipelineRevision,
 pdfData:'data:application/pdf;base64,'+data.toString('base64')}}];

function buildChunks(response,source,receipt){
 if(!Array.isArray(response.pages)||!response.pages.length)throw new Error('OCR returned no pages; no vectors will be published');
 const pages=[...response.pages].sort((a,b)=>a.index-b.index);
 if(pages.some((p,i)=>!Number.isInteger(p.index)||p.index!==i))throw new Error('OCR page sequence is incomplete');
 if(response.usage_info?.pages_processed!=null&&response.usage_info.pages_processed!==pages.length)throw new Error('OCR page count mismatch');
 const chunks=[],limit=3500;let inheritedHeading='';
 const splitWords=(text,max)=>{
   const parts=[];text=text.trim();while(text){let at=text.length<=max?text.length:text.lastIndexOf(' ',max);if(at<=0)at=max;parts.push(text.slice(0,at).trim());text=text.slice(at).trim();}return parts;
 };
 for(const page of pages){
   let markdown=String(page.markdown||'');const images=page.images||[];
   // Some OCR releases return separate table bodies referenced from page markdown.
   for(const table of page.tables||[]){
     if(typeof table.content!=='string')throw new Error('Table body missing on page '+(page.index+1));
     markdown+='\n\n'+table.content;
   }
   const imageReferences=[...markdown.matchAll(/!\[[^\]]*\]\(([^)]*)\)/g)].map(m=>m[1]);
   if(imageReferences.some(ref=>!images.some(img=>String(img.id)===ref)&&!(page.tables||[]).some(t=>String(t.id)===ref)))throw new Error('An image reference has no visual annotation record on page '+(page.index+1));
   const headings=(markdown.match(/^#{1,6}\s+.+$/gm)||[]).join(' / ');
   if(headings)inheritedHeading=headings.slice(0,500);
   const pageContext=(inheritedHeading+'\n'+markdown.split('\n').filter(l=>l.trim()&&!l.trim().startsWith('|')&&!l.trim().startsWith('![')).slice(0,8).join('\n')).slice(0,650);
   const emit=(body,kind,extra={})=>{
     const prefix='DEMO LIBRARY - not linked to an installed IFC object.\nSource: '+source.fileName+' | PDF page '+(page.index+1)+'\n'+pageContext+'\n\n';
     if(!body.trim())return;
     if(body.length>limit)throw new Error('Unexpected oversized content block');
     const chunk_id=receipt.import_id+':'+(chunks.length+1);
     chunks.push({content:prefix+body,metadata:{library:'technical_sheets_demo',demo_only:'true',active:'false',complete:'false',
       source_key:source.source_key,source_file:source.fileName,source_sha256:source.source_sha256,
       pipeline_revision:source.pipeline_revision,embedding_model:'text-embedding-3-small',
       extraction_model:String(response.model||'mistral-ocr-latest'),page:String(page.index+1),content_kind:kind,
       import_id:receipt.import_id,ingestion_started:receipt.started_at,chunk_id,
       section:inheritedHeading,figure_id:extra.figure_id||'',uncertainties:extra.uncertainties||'',
       review_status:extra.uncertainties?'needs_review':'machine_extracted'}});
   };
   // Keep tables together when possible; repeat headers on oversized-table continuations.
   const blocks=[];let accumulated=[],tableMode=null;
   const flush=()=>{if(accumulated.length)blocks.push(accumulated.join('\n'));accumulated=[];tableMode=null;};
   for(const line of markdown.replace(/!\[[^\]]*\]\([^)]*\)/g,'').split('\n')){
     if(!line.trim()){flush();continue;}
     const isTable=line.trim().startsWith('|');if(tableMode!==null&&tableMode!==isTable)flush();
     tableMode=isTable;accumulated.push(line);
   }flush();
   for(const block of blocks){
     if(!block.trim())continue;
     const rows=block.trim().split('\n');
     if(rows.length>2&&rows.every(l=>l.trim().startsWith('|'))){
       const header=rows.slice(0,2).join('\n');let part=header;
       if(header.length>limit/2)throw new Error('Table header too wide; review source page');
       for(const row of rows.slice(2)){
         if(header.length+row.length+1>limit)throw new Error('Table row too wide; review source page');
         if(part.length+row.length+1>limit){emit(part,'table');part=header;}
         part+='\n'+row;
       }emit(part,'table');
     }else for(const part of splitWords(block,limit))emit(part,'text');
   }
   for(const figure of images){
     let annotation=figure.image_annotation;
     if(typeof annotation==='string'){try{annotation=JSON.parse(annotation);}catch{throw new Error('Malformed visual annotation on page '+(page.index+1));}}
     if(!annotation||['kind','description','visible_text','uncertainties'].some(k=>typeof annotation[k]!=='string'))throw new Error('Visual annotation missing on page '+(page.index+1)+'; no silent text-only import');
     const text='Figure '+String(figure.id||'')+' ('+annotation.kind+')\nVision interpretation: '+annotation.description+'\nVisible labels and units: '+annotation.visible_text+'\nUncertainty: '+(annotation.uncertainties||'none reported; machine extraction requires review');
     for(const part of splitWords(text,limit))emit(part,'figure',{figure_id:String(figure.id||''),uncertainties:annotation.uncertainties});
   }
   if(!markdown.trim()&&!images.length)emit('No text or figures extracted on this page. Inspect the source PDF before treating this page as blank.','empty_page',{uncertainties:'No extracted page content'});
 }
 if(!chunks.length)throw new Error('No indexable chunks');
 return {import_id:receipt.import_id,source_key:source.source_key,source_sha256:source.source_sha256,
   started_at:receipt.started_at,pages:pages.length,expected_chunks:chunks.length,chunks};
}
return [{json:buildChunks($json,$('Demo - Prepare PDF Input').item.json,$('Demo - Check Existing Import').item.json)}];

const result=$input.all().map(i=>i.json).find(i=>['IMPORTED','SUPERSEDED','INCOMPLETE'].includes(i.status));
if(!result||result.status==='INCOMPLETE')throw new Error('Vector insertion incomplete or content altered: the document was not published');
return [{json:result}];
